import numpy as np
from ui_styles_ore_ini import ringfill
STYLES = {}

def _plate(rows, letter):
    tmpl = np.array([[int(c, 16) for c in r] for r in rows], np.uint8)
    def style(ink, base):
        art, b = letter(ink, base)
        o = tmpl.copy(); h, w = art.shape
        ty, tx = (o.shape[0] - h) // 2, (o.shape[1] - w) // 2
        sub = o[ty:ty + h, tx:tx + w]
        sub[art > 0] = art[art > 0]
        return o, o.shape[0]
    return style

